package com.hbm.machine.silex;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class SilexContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");private static final DeferredRegister<RecipeType<?>> TYPES=DeferredRegister.create(Registries.RECIPE_TYPE,"hbm");private static final DeferredRegister<RecipeSerializer<?>> SERIALIZERS=DeferredRegister.create(Registries.RECIPE_SERIALIZER,"hbm");
 public static final DeferredBlock<SilexBlock> BLOCK=BLOCKS.register("machine_silex",SilexBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);
 public static final DeferredItem<LaserCrystalItem> CO2=crystal("co2",LaserWavelength.IR),BISMUTH=crystal("bismuth",LaserWavelength.VISIBLE),CMB=crystal("cmb",LaserWavelength.UV),DNT=crystal("dnt",LaserWavelength.GAMMA),DIGAMMA=crystal("digamma",LaserWavelength.DRX);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SilexBlockEntity>> ENTITY=ENTITIES.register("silex",()->BlockEntityType.Builder.of(SilexBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SilexPort>> PORT=ENTITIES.register("silex_port",()->BlockEntityType.Builder.of(SilexPort::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<SilexMenu>> MENU=MENUS.register("silex",()->new MenuType<>((IContainerFactory<SilexMenu>)SilexMenu::new,FeatureFlags.DEFAULT_FLAGS));public static final DeferredHolder<RecipeType<?>,RecipeType<SilexRecipe>> TYPE=TYPES.register("silex",()->new RecipeType<SilexRecipe>(){});public static final DeferredHolder<RecipeSerializer<?>,SilexRecipe.Serializer> SERIALIZER=SERIALIZERS.register("silex",SilexRecipe.Serializer::new);
 private static DeferredItem<LaserCrystalItem> crystal(String type,LaserWavelength wave){String name="laser_crystal_"+type;return ITEMS.register(name,()->new LaserCrystalItem(name,wave));}
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);TYPES.register(bus);SERIALIZERS.register(bus);bus.addListener(SilexContent::capabilities);bus.addListener(SilexControl::register);bus.addListener(SilexRecipes::setup);SilexRecipes.register();}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PORT.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(ITEM.get())):tab.equals("control")?List.of(new ItemStack(CO2.get()),new ItemStack(BISMUTH.get()),new ItemStack(CMB.get()),new ItemStack(DNT.get()),new ItemStack(DIGAMMA.get())):List.of();}
 public static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath("hbm",path);}private SilexContent(){}
}
